\section{Introduction}

\subsection{Divisor theory on graphs}
The theory of divisors on finite graphs, initiated by Baker and Norine, is a
combinatorial shadow of the divisor theory of algebraic curves. A \emph{divisor} on a
graph $G$ is an integer-valued function on its vertices --- a configuration of chips,
possibly negative. The role of principal divisors is played by the image of the graph
Laplacian, that is, by the chip-firing moves; the quotient of degree-zero divisors by
principal divisors is the finite Jacobian, or sandpile group. Most strikingly, there is
an exact analogue of the Riemann--Roch theorem, with canonical divisor
$K(v)=\deg_G(v)-2$ and genus $g=|E|-|V|+1$.

\subsection{The half-canonical degree}
Riemann--Roch determines the rank function completely for divisors of degree $>2g-2$ and
constrains it strongly at all other degrees except one. At $\deg D=g-1$ the right-hand
side of $r(D)-r(K-D)=\deg D-g+1$ vanishes and the identity degenerates into a bare
symmetry $r(D)=r(K-D)$, saying nothing about the common value. This \emph{half-canonical
degree} is the unique locus in the theory that Riemann--Roch leaves open, and it is
exactly where the classical theory of theta characteristics and of Brill--Noether loci is
most interesting.

\subsection{The regular case}
For a $k$-regular graph the canonical divisor is the constant function $k-2$, so
$2g-2=(k-2)n$ with $n=|V|$, and the half-canonical degree is $g-1=\tfrac12(k-2)n$. The
genus ceases to be an independent parameter. The existence question, in the strongest
form one might hope for, asks for a threshold $N_0(k)$ such that every simple connected
$k$-regular graph on at least $N_0(k)$ vertices carries a divisor of degree $g-1$ and
rank at least $k-1$. The scale of $N_0(k)$ was expected to be quadratic, of order $2k^2$,
this being the number of vertices at which the relevant Brill--Noether count first
becomes non-negative. One message of this paper is that this expectation conflated a
dimension count with a construction: for almost all $k$ the correct threshold is
$N_0(k)=1$.

\subsection{Results}
Throughout, ``rank'' means the Baker--Norine rank $r(D)$, defined in
Section~\ref{sec:defs}.

\smallskip
\noindent\textbf{Theorem A} (Receiving-move bound; Theorem~\ref{thm:A}).
\emph{Let $G$ have minimum degree at least $k$ and let $D$ satisfy $D(v)\ge m$ for all
$v$, with $m\ge 1$. Then $r(D)\ge m+t$ for every integer $t$ with $0\le t\le\min(m,k)$;
in particular $r(D)\ge 2m$ whenever $m\le k$.}

\smallskip
\noindent\textbf{Theorem B} (Set-firing bound; Theorem~\ref{thm:B}).
\emph{Let $G$ have minimum degree at least $k$ and let $D$ satisfy $D(v)\ge m$ for all
$v$, with $2\le m\le k$. Then $r(D)\ge\min(3m-1,\,k+m)$.}

\smallskip
\noindent\textbf{Theorem C} (Unconditional half-canonical existence;
Theorems~\ref{thm:C1} and \ref{thm:C2}).
\emph{Let $G$ be a simple $k$-regular graph on $n\ge 1$ vertices with $k\ge 6$. Then $G$
carries a divisor $D$ with $\deg D=g-1$ and $r(D)\ge 3\lfloor (k-2)/2\rfloor-1$.
Consequently, for every $k\ge 6$ with $k\ne 7$, every simple $k$-regular graph carries a
divisor of degree $g-1$ and rank at least $k-1$; one may take $N_0(k)=1$.}

\smallskip
\noindent\textbf{Theorem D} (Pointwise obstruction; Theorem~\ref{thm:D}).
\emph{Let $G$ be $k$-regular and let $2r>k-2$. Then there is no divisor $D$ with
$\deg D=g-1$ and $D(v)\ge r$ for all $v$. In particular this holds for $r=k-1$ and every
$k$.}

\smallskip
\noindent\textbf{Theorem E} (Residual duality; Theorems~\ref{thm:E} and \ref{thm:fixed}).
\emph{The residual map $D\mapsto K-D$ is an involution preserving the half-canonical
degree. Under Riemann--Roch, $r(K-D)=r(D)$ for every $D$ of degree $g-1$, so the
involution maps the set of degree-$(g-1)$ divisors of rank at least $r$ onto itself. A
class is fixed by the involution if and only if it is a theta characteristic
($2D\sim K$), and for such a class the identity holds unconditionally.}

\smallskip
\noindent\textbf{Theorem F} (Self-dual witness; Theorem~\ref{thm:F}).
\emph{On a simple $2j$-regular graph with $j\ge 3$, the constant divisor $D\equiv j-1$ is
a theta characteristic of degree $g-1$, fixed by the residual involution, with
$r(D)\ge 3j-4\ge k-1$.}

\smallskip
\noindent\textbf{Theorem G} (Brill--Noether arithmetic; Section~\ref{sec:bn}).
\emph{At $d=g-1$ the Brill--Noether number satisfies $\rho(g,g-1,r)=g-(r+1)^2$. For a
$k$-regular graph and $r=k-1$, $\rho\ge 1$ if and only if $2k^2\le (k-2)n$; for $k\ge 5$
the linear bound $n\ge 2k+7$ already implies this, and $2k+7\le 2k^2$ for all $k\ge 3$.}

\section{Divisors, chip-firing, and the Baker--Norine rank}\label{sec:defs}

Throughout, $G=(V,E)$ is a finite simple graph with $n=|V|\ge 1$; connectivity is assumed
only where stated. We write $\deg_G(v)$ for the vertex degree and $N(v)$ for the
neighbourhood.

\begin{definition}[Divisor, degree]
A \emph{divisor} on $G$ is a function $D:V\to\mathbb Z$. Its \emph{degree} is
$\deg D=\sum_{v\in V}D(v)$. A divisor is \emph{effective}, written $D\ge 0$, if
$D(v)\ge 0$ for all $v$.
\end{definition}

\begin{definition}[Laplacian and firing]\label{def:lap}
For $f:V\to\mathbb Z$ set
\[
(\Delta f)(v)\;=\;\deg_G(v)\,f(v)\;-\!\!\sum_{u\in N(v)}\! f(u).
\]
For $A\subseteq V$ with indicator $\ind_A$,
\[
(\Delta\ind_A)(v)=
\begin{cases}
\Out(v,A):=|N(v)\setminus A|, & v\in A,\\
-\,|N(v)\cap A|, & v\notin A,
\end{cases}
\]
so \emph{firing the set $A$} --- every vertex of $A$ sends one chip along each of its
edges leaving $A$ --- transforms $D$ into $D-\Delta\ind_A$. Since $\Delta\ind_V=0$,
firing $A$ and firing $V\setminus A$ differ only in sign; equivalently
$D+\Delta\ind_S$ is the result of \emph{firing the complement of $S$}: each vertex of $S$
gains one chip per edge leaving $S$, and each vertex outside $S$ pays one chip per
neighbour inside $S$.
\end{definition}

\begin{definition}[Linear equivalence]
Divisors $D,D'$ are \emph{linearly equivalent}, $D\sim D'$, if $D'=D+\Delta f$ for some
$f:V\to\mathbb Z$. This preserves degree, since $\deg\Delta f=0$.
\end{definition}

\begin{definition}[Baker--Norine rank]\label{def:rank}
For an integer $r\ge 0$ we say $r(D)\ge r$ if for \emph{every} effective divisor $E$ with
$\deg E=r$ there exists $f$ with $D-E+\Delta f\ge 0$. The \emph{Baker--Norine rank}
$r(D)$ is the largest such $r$, with $r(D)=-1$ if $D$ is not linearly equivalent to an
effective divisor. The condition is monotone decreasing in $r$, invariant under linear
equivalence of $D$, and implies $\deg D\ge r$.
\end{definition}

\begin{definition}[Genus, canonical divisor]
The \emph{genus} is $g=|E|-|V|+1$, and the \emph{canonical divisor} is
$K(v)=\deg_G(v)-2$. By the handshake lemma $\deg K=2|E|-2|V|=2g-2$.
\end{definition}

\begin{theorem}[Baker--Norine Riemann--Roch; hypothesis $\RR(G)$]\label{thm:rr}
For a connected graph $G$ and every divisor $D$,
\[
r(D)-r(K-D)=\deg D-g+1 .
\]
\end{theorem}

We treat this identity as a named hypothesis $\RR(G)$ and mark the few statements below
that use it; it is satisfiable, for instance on the one-vertex graph, where $g=0$, all
firings are trivial and $r(D)=\max(-1,\deg D)$.

\begin{remark}
Setting $\deg D=g-1$ in Theorem~\ref{thm:rr} gives $r(D)=r(K-D)$ and nothing more. This
is the half-canonical degree studied here.
\end{remark}

\section{The half-canonical degree of a regular graph}

\begin{lemma}\label{lem:reg}
If $G$ is $k$-regular then $K\equiv k-2$ is constant and $2(g-1)=(k-2)n$.
\end{lemma}

\begin{proof}
$K(v)=\deg_G(v)-2=k-2$; summing, $\deg K=(k-2)n$, and $\deg K=2g-2$.
\end{proof}

Thus the half-canonical degree is $g-1=(k-2)n/2$ and the average number of chips per
vertex is $(k-2)/2\approx k/2$, while the target rank is $k-1$, roughly twice the
average. This already suggests that no argument based purely on local abundance can
succeed.

\begin{theorem}[Theorem D]\label{thm:D}
Let $G$ be $k$-regular with $n\ge 1$ and let $r\ge 0$ satisfy $k-2<2r$. Then there is no
divisor $D$ with $\deg D=g-1$ and $D(v)\ge r$ for all $v$.
\end{theorem}

\begin{proof}
Such a $D$ would satisfy $rn\le\deg D=g-1=(k-2)n/2$, whence $2r\le k-2$, a
contradiction.
\end{proof}

\begin{corollary}
Taking $r=k-1$: since $2(k-1)>k-2$ for every $k\ge 0$, the conjectural rank-$(k-1)$
witnesses are never pointwise dominant. Any proof of half-canonical existence must move
chips.
\end{corollary}

\begin{corollary}\label{cor:optimal}
No divisor of degree $g-1$ on a $k$-regular graph has more than
$m:=\lfloor(k-2)/2\rfloor$ chips at every vertex.
\end{corollary}

\begin{lemma}[Construction of the reserve]\label{lem:reserve}
Let $V\ne\emptyset$, $m\ge 0$ and $d\ge mn$. Then there is a divisor $D$ with
$\deg D=d$ and $D(v)\ge m$ for all $v$.
\end{lemma}

\begin{proof}
Fix $v_0$ and set $D(v_0)=m+(d-mn)$ and $D(v)=m$ otherwise.
\end{proof}

For $d=g-1$ on a $k$-regular graph the hypothesis $mn\le d$ reads $2m\le k-2$. Combining
with Corollary~\ref{cor:optimal}: the constant reserve $m=\lfloor(k-2)/2\rfloor$ is
available and is best possible. The whole problem is to convert a reserve of $m$ into a
rank substantially larger than $m$.

\section{The receiving move}

\begin{lemma}\label{lem:single}
For $v,u\in V$,
\[
(\Delta\ind_{\{v\}})(u)=
\begin{cases}
\deg_G(v), & u=v,\\
-1, & u\sim v,\\
0,&\text{otherwise.}
\end{cases}
\]
Adding $\Delta\ind_{\{v\}}$ gives $v$ one chip along each of its edges, at the cost of
one chip from each neighbour; equivalently, every vertex except $v$ fires.
\end{lemma}

\begin{proof}
Definition~\ref{def:lap} with $A=\{v\}$: $\Out(v,\{v\})=\deg_G(v)$, and
$|N(u)\cap\{v\}|=1$ exactly when $u\sim v$.
\end{proof}

\begin{theorem}[Theorem A]\label{thm:A}
Suppose $\deg_G(v)\ge k$ for all $v$, and let $D$ satisfy $D(v)\ge m$ for all $v$ with
$m\ge 1$. Then $r(D)\ge m+t$ for every $t$ with $0\le t\le m$ and $t\le k$.
\end{theorem}

\begin{proof}
Let $E\ge 0$ with $\deg E=m+t$. If $E\le D$ pointwise, take $f=0$. Otherwise fix $v$ with
$E(v)>D(v)\ge m$, so $E(v)\ge m+1$. For $u\ne v$ effectivity gives
$E(u)+E(v)\le\deg E=m+t$, hence $E(u)\le t-1$; also $E(v)\le m+t$. Take
$f=\ind_{\{v\}}$ and evaluate $D-E+\Delta f$ using Lemma~\ref{lem:single}:
\begin{itemize}
\item at $u=v$: $D(v)-E(v)+\deg_G(v)\ge m-(m+t)+k=k-t\ge 0$;
\item at $u\sim v$: $D(u)-E(u)-1\ge m-(t-1)-1=m-t\ge 0$;
\item at $u\not\sim v$, $u\ne v$: $D(u)-E(u)\ge m-(t-1)>0$.
\end{itemize}
Hence $D-E+\Delta f\ge 0$, and $E$ was arbitrary.
\end{proof}

\begin{corollary}\label{cor:2m}
Under the hypotheses of Theorem~\ref{thm:A} with $m\le k$, $r(D)\ge 2m$.
\end{corollary}

\begin{corollary}
Every simple $k$-regular graph with $k\ge 4$, on any number of vertices, carries a
divisor $D$ with $\deg D=g-1$ and $r(D)\ge 2\lfloor(k-2)/2\rfloor$; for even $k$ this
reads $r(D)\ge k-2$.
\end{corollary}

\begin{proof}
Set $m=\lfloor(k-2)/2\rfloor\ge 1$, apply Lemma~\ref{lem:reserve} (legitimate since
$2m\le k-2$ gives $mn\le g-1$), then Corollary~\ref{cor:2m}.
\end{proof}

For even $k$ this is exactly one unit short of the conjectural rank $k-1$.

\section{One-shot set firing}

\begin{definition}
For $S\subseteq V$ and $v\in S$ write $\Out(v,S)=|N(v)\setminus S|$.
\end{definition}

\begin{lemma}[Set-firing criterion]\label{lem:crit}
Let $S\subseteq V$ and let $D,E$ satisfy
\begin{enumerate}
\item $E(v)-D(v)\le\Out(v,S)$ for every $v\in S$;
\item $|N(u)\cap S|\le D(u)-E(u)$ for every $u\notin S$.
\end{enumerate}
Then $D-E+\Delta\ind_S\ge 0$.
\end{lemma}

\begin{proof}
By Definition~\ref{def:lap}, at $v\in S$ the value is $D(v)-E(v)+\Out(v,S)\ge 0$ by (1),
and at $u\notin S$ it is $D(u)-E(u)-|N(u)\cap S|\ge 0$ by (2).
\end{proof}

\begin{lemma}\label{lem:outdeg}
If $v\in S$ then $\Out(v,S)\ge\deg_G(v)-(|S|-1)$.
\end{lemma}

\begin{proof}
$N(v)\cap S\subseteq S\setminus\{v\}$ since $G$ is simple, so $|N(v)\cap S|\le|S|-1$,
and $\Out(v,S)=\deg_G(v)-|N(v)\cap S|$.
\end{proof}

\begin{theorem}[Theorem B]\label{thm:B}
Suppose $\deg_G(v)\ge k$ for all $v$. Let $D$ satisfy $D(v)\ge m$ for all $v$, with
$2\le m\le k$, and let $d$ be an integer with $d+1\le 3m$ and $d\le k+m$. Then
$r(D)\ge d$. Equivalently, $r(D)\ge\min(3m-1,\,k+m)$.
\end{theorem}

\begin{proof}
Let $E\ge 0$ with $\deg E=d$. If $E\le D$ pointwise take $f=0$; otherwise fix $v_0$ with
$E(v_0)>D(v_0)\ge m$, i.e.\ $E(v_0)\ge m+1$. Define the \emph{trouble set}
\[
S=\{u\in V: E(u)\ge m\}\ni v_0 .
\]

\emph{Step 1: $|S|\le 2$.} Since $E\ge 0$, for any $T\subseteq V$ we have
$\sum_{u\in T}E(u)\le\deg E=d$. Applying this to $T=S$ and bounding each term below
--- every $u\in S$ contributes at least $m$, and $v_0$ at least $m+1$ --- gives
\begin{equation}\label{eq:count}
|S|\,m+1\ \le\ \sum_{u\in S}E(u)\ \le\ d\ \le\ 3m-1 .
\end{equation}
If $|S|\ge 3$ then $3m+1\le 3m-1$, absurd; and $|S|\ge 1$.

\emph{Step 2: load outside $S$.} By definition, $E(u)\le m-1$ for $u\notin S$; and
applying $\sum_T E\le d$ to $T=S\cup\{u\}$ together with the lower bound in
\eqref{eq:count},
\begin{equation}\label{eq:outside}
E(u)\ \le\ d-|S|\,m-1 \qquad(u\notin S).
\end{equation}

\emph{Step 3: load inside $S$.} For $v\in S$ the other $|S|-1$ elements each carry at
least $m$ chips of $E$, so
\begin{equation}\label{eq:inside}
E(v)\ \le\ d-(|S|-1)\,m .
\end{equation}

\emph{Step 4: verify Lemma~\ref{lem:crit}.}

\emph{Case $|S|=1$, $S=\{v_0\}$.} For (1): by \eqref{eq:inside}, $E(v_0)\le d\le k+m$,
while $D(v_0)\ge m$ and $\Out(v_0,S)=\deg_G(v_0)\ge k$; hence
$E(v_0)-D(v_0)\le k\le\Out(v_0,S)$. For (2): $|N(u)\cap S|\le 1$ while
$D(u)-E(u)\ge m-(m-1)=1$.

\emph{Case $|S|=2$.} For (1): \eqref{eq:inside} gives $E(v)\le d-m\le 2m-1$ and
Lemma~\ref{lem:outdeg} gives $\Out(v,S)\ge k-1$, so
$E(v)-D(v)\le (2m-1)-m=m-1\le k-1\le\Out(v,S)$, using $m\le k$. For (2):
$|N(u)\cap S|\le 2$ while \eqref{eq:outside} gives $E(u)\le d-2m-1\le m-2$, so
$D(u)-E(u)\ge m-(m-2)=2$.

In both cases Lemma~\ref{lem:crit} supplies $f=\ind_S$ with $D-E+\Delta f\ge 0$.
\end{proof}

\begin{remark}
The bound $d\le 3m-1$ is used twice and is the crux: once in Step~1 to force $|S|\le 2$,
once in Case $|S|=2$ to make an outside vertex able to afford \emph{two} chips rather
than one. The bound $d\le k+m$ is used only in Case $|S|=1$. The hypothesis $m\ge 2$ is
needed for \eqref{eq:count} to bite, and $m\le k$ in Case $|S|=2$.
\end{remark}

\begin{remark}
For $m\le k$ this improves the bound $2m$ of Corollary~\ref{cor:2m} by roughly fifty
percent. Both terms in the minimum are genuinely present: Section~\ref{sec:comp} exhibits
$K_7$ ($k=6$, $m=2$) where the true rank is $5=3m-1$ while $k+m=8$.
\end{remark}

\section{Unconditional half-canonical existence}

\begin{theorem}\label{thm:C1}
Let $G$ be a simple $k$-regular graph on $n\ge 1$ vertices with $k\ge 6$. Then there is a
divisor $D$ with $\deg D=g-1$ and $r(D)\ge 3\lfloor(k-2)/2\rfloor-1$.
\end{theorem}

\begin{proof}
Put $m=\lfloor(k-2)/2\rfloor$; since $k\ge 6$ we have $m\ge 2$, and $m\le k$. As
$2m\le k-2$, Lemma~\ref{lem:reg} gives $mn\le g-1$, so Lemma~\ref{lem:reserve} yields
$D$ with $\deg D=g-1$ and reserve $m$. Apply Theorem~\ref{thm:B} with $d=3m-1$: the
hypothesis $d+1\le 3m$ is an equality, and $d\le k+m$ is equivalent to $2m\le k+1$, which
follows from $2m\le k-2$.
\end{proof}

\begin{theorem}\label{thm:C2}
For every $k\ge 6$ with $k\ne 7$, every simple $k$-regular graph on any number of
vertices carries a divisor of degree $g-1$ with rank at least $k-1$. Equivalently, the
uniform half-canonical existence statement holds for such $k$ with threshold $N_0(k)=1$.
\end{theorem}

\begin{proof}
It suffices to check $3\lfloor(k-2)/2\rfloor-1\ge k-1$. If $k=2j$ then
$\lfloor(k-2)/2\rfloor=j-1$ and the inequality reads $3j-4\ge 2j-1$, i.e.\ $j\ge 3$,
i.e.\ $k\ge 6$. If $k=2j+1$ then $k-2=2j-1$ and again $\lfloor(k-2)/2\rfloor=j-1$, so the
inequality reads $3j-4\ge 2j$, i.e.\ $j\ge 4$, i.e.\ $k\ge 9$. Thus it holds for all
$k\ge 6$ except $k=7$, where $3j-4=5<6$.
\end{proof}

\begin{remark}\label{rem:excluded}
The proof fails exactly when $m=\lfloor(k-2)/2\rfloor$ is too small: at $k=5$ we get
$m=1$ and Theorem~\ref{thm:B} does not apply (only Theorem~\ref{thm:A}, giving rank
$\ge 2$); at $k=7$ we get $m=2$ and $3m-1=5$ falls one short of $6$.
Section~\ref{sec:comp} shows both shortfalls are real.
\end{remark}

\begin{remark}\label{rem:witness}
The witness is explicit: place $\lfloor(k-2)/2\rfloor$ chips at every vertex and the
leftover $g-1-mn$ chips at a single arbitrary vertex. For even $k$ the leftover is zero
and the witness is the constant divisor $(k-2)/2$.
\end{remark}

\section{Residual duality and theta characteristics}

\begin{definition}
The \emph{residual} of a divisor is $\res(D)=K-D$.
\end{definition}

\begin{proposition}\label{prop:invol}
$\res$ is an involution, and $\deg\res(D)=2g-2-\deg D$; in particular $\res$ preserves
the half-canonical degree $g-1$.
\end{proposition}

\begin{proof}
Immediate from $\deg K=2g-2$.
\end{proof}

\begin{theorem}[Theorem E]\label{thm:E}
Assume $\RR(G)$. If $\deg D=g-1$ then $r(\res(D))=r(D)$. Consequently, for every $r$, the
involution $\res$ maps $\{[D]:\deg D=g-1,\ r(D)\ge r\}$ onto itself.
\end{theorem}

\begin{proof}
Substituting $\deg D=g-1$ into Theorem~\ref{thm:rr} gives $r(D)-r(K-D)=0$; the second
claim follows from Proposition~\ref{prop:invol}.
\end{proof}

\begin{definition}
A divisor $D$ is a \emph{theta characteristic} if $2D\sim K$.
\end{definition}

\begin{theorem}\label{thm:fixed}
$D\sim\res(D)$ if and only if $D$ is a theta characteristic. Moreover every theta
characteristic has degree $g-1$.
\end{theorem}

\begin{proof}
$D\sim K-D$ means $K-D=D+\Delta f$, i.e.\ $D+D=K+\Delta(-f)$, i.e.\ $2D\sim K$. For the
degree, $2\deg D=\deg K=2g-2$.
\end{proof}

\begin{corollary}
If $D$ is a theta characteristic then $r(\res(D))=r(D)$ with no appeal to $\RR(G)$: the
two divisors are linearly equivalent and rank is a class invariant.
\end{corollary}

\begin{theorem}[Theorem F]\label{thm:F}
Let $G$ be a simple $2j$-regular graph with $j\ge 3$. Then the constant divisor
$D\equiv j-1$ satisfies: $2D=K$ exactly (so $D$ is a theta characteristic and
$D\sim\res(D)$); $\deg D=g-1$; and $r(D)\ge 3j-4\ge k-1$, where $k=2j$.
\end{theorem}

\begin{proof}
$K\equiv 2j-2=2(j-1)$, so $D+D=K$ on the nose. The degree claim is
Theorem~\ref{thm:fixed}. For the rank apply Theorem~\ref{thm:B} with $m=j-1\ge 2$,
$k=2j\ge m$ and $d=3j-4$: then $d+1=3m$ and $d\le k+m=3j-1$. Finally $3j-4\ge 2j-1$ iff
$j\ge 3$.
\end{proof}

Thus for even $k\ge 6$ the half-canonical witness may be taken maximally symmetric:
constant on the graph, and equal to its own residual.

\section{Brill--Noether arithmetic at the half-canonical degree}\label{sec:bn}

Classical Brill--Noether theory predicts the dimension of the family of linear systems of
degree $d$ and rank $r$ on a genus-$g$ curve to be
$\rho(g,d,r)=g-(r+1)(g-d+r)$.

\begin{lemma}\label{lem:rho}
$\rho(g,g-1,r)=g-(r+1)^2$.
\end{lemma}

\begin{proof}
$g-(r+1)(g-(g-1)+r)=g-(r+1)(1+r)=g-(r+1)^2$.
\end{proof}

\begin{theorem}[Exact positivity criterion]\label{thm:bniff}
Let $G$ be $k$-regular on $n$ vertices. Then
$\rho(g,g-1,k-1)\ge 1$ if and only if $2k^2\le (k-2)n$.
\end{theorem}

\begin{proof}
By Lemma~\ref{lem:rho} the condition is $g-k^2\ge 1$, i.e.\ $2g-2\ge 2k^2$; and
$2g-2=(k-2)n$ by Lemma~\ref{lem:reg}.
\end{proof}

\begin{corollary}
If $k\ge 3$ and $n\ge 2k^2$ then $\rho(g,g-1,k-1)\ge 1$.
\end{corollary}

\begin{theorem}[Linear sufficiency]\label{thm:linear}
If $k\ge 5$ and $n\ge 2k+7$ then $\rho(g,g-1,k-1)\ge 1$.
\end{theorem}

\begin{proof}
$(k-2)(2k+7)=2k^2+3k-14\ge 2k^2$ because $3k\ge 15>14$; monotonicity in $n$ finishes.
\end{proof}

\begin{corollary}
For $k\ge 3$, $2k+7\le 2k^2$. Hence the quadratic scale $2k^2$ is not forced by the
Brill--Noether count.
\end{corollary}

\begin{discussion}
Theorems~\ref{thm:bniff}--\ref{thm:linear} explain the provenance of the quadratic guess
$N_0(k)\approx 2k^2$: it is the scale at which the expected \emph{dimension} of the
family of half-canonical rank-$(k-1)$ systems becomes positive. But positive expected
dimension is neither necessary nor sufficient for existence on a specific graph, and
Theorem~\ref{thm:C2} shows how far it is from necessary: the true threshold is $1$ for
all $k\ge 6$, $k\ne 7$, while even the weakened linear criterion needs $n\ge 2k+7$. The
Brill--Noether count and the chip-firing construction measure different things.
\end{discussion}

\section{Computational evidence}\label{sec:comp}

Baker--Norine ranks on small graphs can be computed exactly by reducing each candidate
divisor to its $q$-reduced representative (a maximal-firing normal form obtained by
Dhar's burning algorithm), testing effectivity, and searching over all effective divisors
of each degree in turn. The following are exact values obtained by exhaustive
computation.

\begin{center}
\begin{tabular}{@{}lccclccl@{}}
\toprule
Graph & $k$ & $n$ & $g$ & Divisor & $\deg$ & Rank & Bound $\min(3m-1,k+m)$\\
\midrule
$K_6$ & $5$ & $6$ & $10$ & constant $2$ & $12$ & $5$ & $\min(5,7)=5$ attained\\
$K_6$ & $5$ & $6$ & $10$ & $(4,1,1,1,1,1)$ & $9=g-1$ & $2$ & --- ($m=1$)\\
$K_6$ & $5$ & $6$ & $10$ & \emph{all} of degree $9$ & $9=g-1$ & $\max=2$ & ---\\
$K_7$ & $6$ & $7$ & $15$ & constant $2$ & $14=g-1$ & $5$ & $\min(5,8)=5$ attained\\
$K_8$ & $7$ & $8$ & $21$ & $(6,2,\dots,2)$ & $20=g-1$ & $5$ & $\min(5,9)=5$ attained\\
$C_8(1,2,3)$ & $6$ & $8$ & $17$ & constant $2$ & $16=g-1$ & $5$ & $\min(5,8)=5$ attained\\
$C_9(1,2,3)$ & $6$ & $9$ & $19$ & constant $2$ & $18=g-1$ & $5$ & $\min(5,8)=5$ attained\\
$K_{5,5}$ & $5$ & $10$ & $16$ & $(2^5,1^5)$ & $15=g-1$ & $5$ & --- ($m=1$)\\
\bottomrule
\end{tabular}
\end{center}

Three conclusions.

\smallskip
\noindent\textbf{(a) The set-firing bound is attained, not merely approached.} In five
rows the computed rank equals $3m-1$ exactly. On $K_7$ the true rank is $5=3m-1$ while
$k+m=8$: the minimum in Theorem~\ref{thm:B} is realised by the $3m-1$ branch, which
therefore cannot be removed.

\smallskip
\noindent\textbf{(b) At $k=7$ the shortfall is real.} On $K_8$ the natural witness of
degree $g-1=20$ has rank exactly $5=k-2$, one below the target $6$, precisely the deficit
predicted by Remark~\ref{rem:excluded}.

\smallskip
\noindent\textbf{(c) At $k=5$ a genuine threshold is required.} An exhaustive search over
\emph{all} effective divisors of degree $9$ on $K_6$ --- hence over all degree-$9$
classes of non-negative rank --- finds maximal rank $2$, far below the target $4$.
Therefore $N_0(5)>6$. On the other hand $K_{5,5}$, also $5$-regular, carries a
degree-$(g-1)$ divisor of rank $5>4$. So at $k=5$ the maximal half-canonical rank is not
a function of $n$ alone, and any proof must select its witness using structural
information.

\section{Discussion and open problems}

\subsection{What was actually needed}
Theorem~\ref{thm:C2} consumes remarkably little machinery: no spectral hypothesis, no
expansion, no bound on $n$, no probabilistic argument, no appeal to Riemann--Roch --- a
single firing of the complement of an explicitly described set of size at most two. The
problem looked hard because the natural first move (Theorem~\ref{thm:A}) lands exactly
one unit short for even $k$, and the natural first estimate (the Brill--Noether count)
suggests a quadratic threshold. Both are misleading, and Theorem~\ref{thm:D} says where
the real difficulty lies: not in finding enough chips, but in moving them.

\begin{problem}
Determine whether finite thresholds $N_0(5)$, $N_0(7)$ exist, and bound them. The
computations show $N_0(5)>6$, so unlike the settled degrees the statement at $k=5$ is
genuinely asymptotic. These are exactly the degrees where $\lfloor(k-2)/2\rfloor\in\{1,2\}$
and one-shot firing is too weak. A natural approach is \emph{iterated} set firing, with
the trouble set recomputed after each move; the counting argument of Step~1 of
Theorem~\ref{thm:B} has an obvious multi-step analogue, but the cost accounting outside
$S$ becomes considerably more delicate.
\end{problem}

\begin{problem}
At $k=5$, characterise the $5$-regular graphs whose maximal half-canonical rank is small.
The contrast between $K_6$ (rank $2$) and $K_{5,5}$ (rank $5$) suggests bipartiteness,
girth, or expansion as candidate discriminants.
\end{problem}

\begin{problem}
Show that for every $k\ge 5$ there are infinitely many $k$-regular graphs on which the
uniform witness of Remark~\ref{rem:witness} has rank exactly
$\min(3\lfloor(k-2)/2\rfloor-1,\ k+\lfloor(k-2)/2\rfloor)$ --- i.e.\ that
Theorem~\ref{thm:B} is asymptotically sharp for uniform witnesses and cannot be improved
to $k+m$ by any refinement of one-shot firing. Attainment at $k=5,6,7$ is already
exhibited above; the content is to produce infinite families, presumably among circulants
or Cayley graphs.
\end{problem}

\begin{problem}
For every $\varepsilon>0$, is there $C(\varepsilon)$ such that every connected
$k$-regular graph with normalised spectral gap at least $\varepsilon$ and
$n\ge C(\varepsilon)k$ carries a degree-$(g-1)$ divisor of rank at least $k-1$? Expansion
should make chip redistribution uniform enough to replace counting by mixing; the
interest is now concentrated on $k\in\{5,7\}$.
\end{problem}

\begin{problem}
For fixed $k$, does the proportion of effective divisors of degree $g-1$ having rank at
least $k-1$ tend to $1$ as $n\to\infty$, uniformly over simple connected $k$-regular
graphs? A uniform counting statement would simultaneously prove existence and explain the
insensitivity of the answer to fine structure. The $K_6$ computation shows the statement
cannot be made non-asymptotic.
\end{problem}

\begin{problem}
Exploit the involution algorithmically: an exhaustive search for half-canonical witnesses
need only examine one class per residual pair, together with the theta characteristics.
On a graph with Jacobian $J$, the number of theta characteristics is $|J[2]|$ when one
exists, so the reduction is essentially by a factor of two.
\end{problem}

\begin{problem}
For which graphs is the maximal half-canonical rank attained at a theta characteristic?
Theorem~\ref{thm:F} shows this happens for every even-regular graph with $k\ge 6$; the
odd-regular case has no constant theta characteristic and the question is open.
\end{problem}

\subsection*{Summary of logical dependencies}
Theorem~\ref{thm:A} depends only on Lemma~\ref{lem:single} and effectivity bookkeeping.
Theorem~\ref{thm:B} depends on Lemmas~\ref{lem:crit} and \ref{lem:outdeg} and on the
counting inequality \eqref{eq:count}; it is independent of Theorem~\ref{thm:A}.
Theorem~\ref{thm:C1} combines Lemmas~\ref{lem:reg} and \ref{lem:reserve} with
Theorem~\ref{thm:B}, and Theorem~\ref{thm:C2} adds the parity computation.
Theorem~\ref{thm:F} combines Theorems~\ref{thm:B} and \ref{thm:fixed}. Only
Theorem~\ref{thm:E} uses the Riemann--Roch identity $\RR(G)$; in particular the main
existence theorem does not use Riemann--Roch at all.

\end{document}

