"""
Algorithm 1: q-reduced divisors via Dhar's burning algorithm.

Given a connected graph G, a divisor D and a distinguished vertex q, there is a
unique divisor linearly equivalent to D that is *q-reduced*: non-negative away
from q, and such that no non-empty subset of V \\ {q} can fire without pushing
some vertex into debt.  The q-reduced representative is a normal form for the
divisor class, and D is linearly equivalent to an effective divisor if and only
if its q-reduced representative is itself effective.

The computation has two stages.  Stage 1 ("benevolence") sweeps the graph in
layers of increasing distance from q, borrowing along each layer until no vertex
other than q is in debt; this terminates because each sweep strictly decreases
the total debt of the layers processed so far.  Stage 2 (Dhar's burning
algorithm) repeatedly starts a fire at q: a vertex burns as soon as the number
of burnt neighbours exceeds its chip count.  If the fire does not consume the
whole graph, the unburnt set can fire without creating debt, and one does so;
each such firing strictly decreases the value at q, so the loop terminates.
"""

from collections import deque
from typing import List, Sequence

Graph = List[List[int]]
Divisor = List[int]


def bfs_distances(g: Graph, q: int) -> List[int]:
    """Graph distances from q, by breadth-first search.  O(|V| + |E|)."""
    dist = [-1] * len(g)
    dist[q] = 0
    queue = deque([q])
    while queue:
        v = queue.popleft()
        for u in g[v]:
            if dist[u] < 0:
                dist[u] = dist[v] + 1
                queue.append(u)
    return dist


def fire_complement(g: Graph, d: Divisor, s: Sequence[int]) -> None:
    """
    In place: fire V \\ S.  Each vertex of S gains one chip per edge leaving S;
    each vertex outside S pays one chip per neighbour inside S.  O(|E|).
    """
    inside = set(s)
    for v in range(len(g)):
        if v in inside:
            d[v] += sum(1 for u in g[v] if u not in inside)
        else:
            d[v] -= sum(1 for u in g[v] if u in inside)


def q_reduce(g: Graph, d: Divisor, q: int = 0) -> Divisor:
    """The unique q-reduced divisor linearly equivalent to d."""
    out = list(d)

    # Stage 1: benevolence, layer by layer, farthest layer first.
    dist = bfs_distances(g, q)
    for layer in range(max(dist), 0, -1):
        s = [v for v in range(len(g)) if dist[v] >= layer]
        while any(out[v] < 0 for v in s):
            fire_complement(g, out, s)

    # Stage 2: Dhar's burning algorithm.
    while True:
        burnt = {q}
        changed = True
        while changed:
            changed = False
            for v in range(len(g)):
                if v in burnt:
                    continue
                if sum(1 for u in g[v] if u in burnt) > out[v]:
                    burnt.add(v)
                    changed = True
        if len(burnt) == len(g):
            return out
        fire_complement(g, out, list(burnt))


def is_equivalent_to_effective(g: Graph, d: Divisor, q: int = 0) -> bool:
    """True iff d is linearly equivalent to an effective divisor."""
    return all(x >= 0 for x in q_reduce(g, d, q))
